import utils from "@/environments/utils";
import React, { useEffect, useState } from "react";
import Store from './store';
import { FormBusinessContext } from "../contexts/FormBusinessContext";
import { useObserver } from "mobx-react-lite";
// import config from "@/environments/hoc";

export default ({ value, children }: any) => {
    const [store] = useState(() => new Store());
    const BusinessContext: any = null;
    // const [BusinessContext] = useState(() => {
    //     return config.state.contexts["system_business"];
    // })

    useEffect(() => {
        const { tableId, modelKey } = value || {};
        if(!tableId) {
            store.unInit();
        }else {
            store.init(value);
        };
        console.log('value', value);
    },[value?.tableId])

    return useObserver(() => {

        return (
            <BusinessContext.Provider value={value}>
                <FormBusinessContext.Provider value={store.businessObj}>
                    {children}
                </FormBusinessContext.Provider>
            </BusinessContext.Provider>
        )
    })
}