import utils from '@/environments/utils';
import { action, observable, computed, toJS, makeObservable } from 'mobx';
import React from 'react';
import { FormContextProps } from "@/components/contexts/FormBusinessContext";
import business from '@/store/business';

class Store {
    @observable values: FormContextProps = {};
    @action setValues = (val) => {
        this.values = val;
    }

    constructor() {
        makeObservable(this);
    }

    @computed get businessObj(){
        return toJS(this.values);
    }

    init = async (value) => {
        const { tableId, modelKey, itemId } = value;
        if(business.info[tableId]) {
            this.setValues({ ...business.info[tableId], modelKey, itemId })
            return;
        }

        const fields = await utils.ajax.get('/custom/table/fields', {
            customTableInfoId: tableId
        })
        const tables = await utils.ajax.get('/custom/relation/itemTable', {
            tableId
        })
        business.setInfo(tableId, { fields, tables })
        this.setValues({ fields, tables, modelKey, itemId })
    }


    unInit = () => {
        this.setValues({});
    }
}

export default Store;