import React from 'react';
import { CustomPageStore, defineConfig, moduleStore } from "react-converter-code";
import { Switch, Modal, Select, Image } from "@arco-design/web-react";
import Icon from '@/components/Icon';
import mainConfig from 'mainConfig';
import { getModuleList } from '@/utils/api';
import globals, { dynamicCreateModule } from "@/environments/hoc"
import { systemList, allList } from "@/environments/database";
import FormBusiness from '@/components/FormBusiness';
import EditRoute from "@/components/PageRoute/EditRoute";
import { htmlModuleList } from '@/utils/database';
import ajax from '@/utils/ajax';
import fileStore from '@/store/file';
import { ModuleItem } from "@/components/CustomPage/interface";

/**
 * 这边为了兼容image 静态资源做兼容处理
 */
globals.h = ((...args: [any, any]) => {
    let [name, props, ...children] = args;
    switch(name){
        case 'img':
        case 'image':
            if(fileStore.imgMap[props.src]){
                props = { ...props, src: fileStore.imgMap[props.src], alt: props.src }
            }
        break;
        case Image:
            if(fileStore.imgMap[props.src]){
                props = { ...props, src: fileStore.imgMap[props.src], alt: props.src }
            }
        break;
        case Image.Preview:
            if(fileStore.imgMap[props.src]){
                props = { ...props, src: fileStore.imgMap[props.src], alt: props.src }
            }
        break;
        case Image.PreviewGroup:
            if(props.srcList && Array.isArray(props.srcList) && props.srcList.length){
                props = {
                    ...props,
                    srcList: props.srcList.map((url) => {
                        if(fileStore.imgMap[url]) return fileStore.imgMap[url];
                        return url;
                    })
                }
            }
        break;
    }
    return React.createElement(name, props, ...children)
}) as any



defineConfig({
    // @ts-ignore
    typescriptURL: mainConfig.typescriptURL,
    lessURL: "https://wizui-assets.oss-cn-hangzhou.aliyuncs.com/umd/less%404.2.0/less.min.js",
    parse: true,
    parseConfig: {
        saveCustomModule: async (pages: CustomPageStore[]) => {
            // const element = moduleStore.elements.get(mStore.key);
            const names = pages.map((page) => {
                const element = moduleStore.elements.get(page.uid);
                return element.nickname || element.name
            }).join(',')
            return new Promise((resolve, reject) => {
                Modal.confirm({
                    title: "更新组件",
                    content: `您修改了${names}组件信息，请确认是否保存`,
                    onCancel: reject,
                    onOk: async () => {
                        const result = pages.slice().reverse();
                        for (const page of result) {
                            const data = page.getData();
                            const resProps = {
                                props: data.page.props,
                                content: data,
                                jsxRender: await page.getRenderText(),
                            }
                            const element = moduleStore.elements.get(page.uid);
                            await ajax.post('/apijson/put', {
                                Module: {
                                    id: element.uid,
                                    ...resProps,
                                    content: JSON.stringify(data),
                                }
                            }).then(() => {
                                moduleStore.updateElement(page.uid, {
                                    ...element,
                                    ...resProps
                                })
                            })
                        }
                        resolve(true);
                    }
                })
            })
        }
    },
    schema: {
        sources: {
            // "featchOptions": {
            //     funName: "featchOptions"
            // },
            // "featch": {
            //     funName: "featchData"
            // }
        },
        // pageInjectedVars: [ "forms" ],
    } as any,
    modules: {
        // 编辑模式下调用
        getRender: (item: ModuleItem) => {
            const { key, source, name } = item;
            // console.log('state', key, source, config)
            let render: any =  () => null;
            switch(source){
                case "error":
                    render = () => `模块丢失：${key}`;
                break;
                case "arco":
                    render = globals.state.mModules[key] || (() => key);
                break;
                case "custom":
                    if(item.jsxRender){
                        // console.log('custom-item', item)
                        render = dynamicCreateModule(item.jsxRender)
                    }
                    globals.state.mModules[item.key] = render;
                break;
                case "context":
                    if(!globals.state.contexts[item.key]){
                        globals.state.contexts[item.key] = React.createContext(item.extraInfo.defaultProps);
                    }
                    if(item.key === "system_business"){
                        render = FormBusiness;
                    }else {
                        render = globals.state.contexts[item.key].Provider;
                    }
                    globals.state.mModules[item.key] = render;
                break;
                default:
                    render = globals.m(key);
            }
            if(render && render.preload){
                render.preload(); // 预加载
            }
            return render;
        },
        getIcon: (value) => React.createElement(Icon as any, { value, key: value })
    } as any,
    api: {
        getModuleList: getModuleList
    },
    dependencies: {
        arco: "@arco-design/web-react",
        arcos: "@arco-design/web-react/icon"
    },
    run: globals,
})


htmlModuleList.forEach((o: any) => {
    const render = (props) => {
        const { children, ...params } = props;
        const list = React.Children.toArray(children);
        return React.createElement(o.key, params, ...list)
    }
    o.render = render;
    if(o.key === 'img'){
        o.render = (props) => {
            let { children, ...params } = props;
            if(fileStore.imgMap[params.src]){
                params = { ...params, src: fileStore.imgMap[props.src], alt: props.src }
            }
            const list = React.Children.toArray(children);
            return React.createElement(o.key, params, ...list)
        }
    }
    moduleStore.elements.set(o.key, o);
})

const getEditRender = (o) => {
    switch(o.key){
        case "system_page_route":
            return EditRoute;
        default:
            return globals.m(o.key);
    }
}
systemList.forEach((o) => {
    moduleStore.addElement({
        ...o,
        render: getEditRender(o)
    } as any);
})
allList.forEach((o) => {
    moduleStore.addElement({
        ...o,
        render: getEditRender(o),
    } as any);
})
